import { isValidId } from '../utils';

/** Decode + validate a continuation token. Rejects IDs that cannot be
 * generated by nanoid and tokens whose issue timestamp is older than the
 * execution-state TTL. */
export function decodeContinuationToken(
  token: string,
  maxAgeMs: number,
): { execution_id: string } | null {
  try {
    const parsed: unknown = JSON.parse(
      Buffer.from(token, 'base64').toString('utf-8'),
    );
    if (parsed === null || typeof parsed !== 'object') {
      return null;
    }
    const candidate = parsed as { execution_id?: unknown; ts?: unknown };
    if (
      typeof candidate.execution_id !== 'string' ||
      !isValidId(candidate.execution_id)
    ) {
      return null;
    }
    if (typeof candidate.ts === 'number' && Number.isFinite(candidate.ts)) {
      const ageMs = Date.now() - candidate.ts;
      if (ageMs > maxAgeMs) {
        return null;
      }
    }
    return { execution_id: candidate.execution_id };
  } catch {
    return null;
  }
}
